// Test-owned correlation predicates only: no tokens, credential IDs, raw scope,
// actor/session identifiers or report bodies. This snapshot is not a socket.
include!("next_lc1_movement_predicates.rs");
fn recovery_owner_predicates<S:CredentialStore>(c:&Core<S>)->Value {
  let eligibility=movement_gate_predicates(c);
  let pending=c.pending.lock().unwrap().clone();let control_valid=pending.as_ref().is_some_and(|p|c.validate_current_admission(p).is_ok());let movement_ready=pending.as_ref().is_some_and(|p|c.lc1_live_movement_ready(p));
  let lifecycle=c.lifecycle.lock().unwrap();let authority=&lifecycle.authority;let canonical=authority.admission.as_ref();let current=canonical.and_then(|a|a.current_report.as_ref());
  let token_matches=c.game.as_ref().and_then(|g|admission::token_id(g.session.access.as_str()).ok()).is_some_and(|id|canonical.and_then(|a|a.sample.as_ref()).and_then(|s|s.credential_id.as_deref())==Some(id.as_str()));
  let scope_matches=c.game.as_ref().zip(canonical.and_then(|a|a.scope.as_ref())).is_some_and(|(g,s)|s.principal_id.as_deref()==Some(&g.session.account)&&s.session_id.as_deref()==Some(&g.session.id)&&s.session_epoch.as_deref()==Some(&g.session.epoch)&&s.attachment_id.as_deref()==Some(&g.session.attachment));
  let owner_matches=c.game.as_ref().zip(canonical.and_then(|a|a.owner.as_ref())).is_some_and(|(g,o)|o.game_session_id.as_deref()==Some(&g.session.id)&&o.game_session_epoch.as_deref()==Some(&g.session.epoch)&&o.attachment_id.as_deref()==Some(&g.session.attachment)&&o.game_instance_id.as_deref()==Some(uuid::Uuid::from_bytes(g.owner.1).to_string().as_str()));
  let desktop_matches=c.desktop.as_ref().zip(canonical.and_then(|a|a.owner.as_ref())).is_some_and(|(d,o)|o.desktop_id.as_deref()==Some(&d.id)&&o.desktop_session_epoch.as_deref()==Some(&d.epoch));
  let record_matches=c.world.record.as_ref().zip(canonical.and_then(|a|a.scope.as_ref())).is_some_and(|(r,s)|s.room_id.as_deref()==Some(&r.identity.room)&&s.run_id.as_deref()==Some(&r.identity.run)&&s.run_epoch.as_deref()==Some(&r.identity.run_epoch)&&s.world_token.as_deref()==Some(r.world.to_string().as_str())&&s.config_revision.map(u64::from)==Some(r.identity.config));
  json!({"game_present":c.game.is_some(),"game_entered_locally":c.game.as_ref().is_some_and(|g|g.entered),"game_reported_sequence":c.game.as_ref().map(|g|g.reported),
   "native_owner_matches_game":pending.as_ref().zip(c.game.as_ref()).is_some_and(|(p,g)|p.owner==Some(g.owner)),"native_report_context_matches_game":pending.as_ref().and_then(|p|p.observation.as_ref()).zip(c.game.as_ref()).is_some_and(|(r,g)|r.context==g.owner.1),
   "canonical_generation":canonical.and_then(|a|a.generation),"record_lifecycle_generation":c.world.record.as_ref().map(|r|r.canonical_generation),"canonical_content_matches_native":current.and_then(|r|r.content_digest.as_deref()).zip(pending.as_ref().and_then(|p|p.observation.as_ref())).is_some_and(|(digest,r)|digest==hex(&r.digest)),
   "canonical_scope_matches_game":scope_matches,"canonical_owner_matches_game":owner_matches,"canonical_owner_matches_desktop":desktop_matches,"canonical_scope_matches_record":record_matches,
   "canonical_report":current.map(|r|json!({"revision":r.revision,"protected":r.protected,"loaded":r.loaded,"complete":r.complete,"content_valid":r.content_valid})),"canonical_decision":canonical.and_then(|a|a.decision.as_ref()).map(|d|json!({"authorized":d.authorized,"playing":d.playing,"terminal":d.terminal})),
   "eligibility":eligibility,"movement_eligibility_ready":movement_ready,"production_movement_gate_enabled":true,"control_validation_accepts":control_valid,"token_matches_canonical_sample":token_matches,"canonical_authority_live":authority.authority.live(Instant::now()),"offered":authority.offered,"entered":authority.entered,
   "native":pending.as_ref().map(|p|json!({"release":p.release,"authority_live":p.authority_until>Instant::now(),"report":p.observation.as_ref().map(|r|json!({"sequence":r.sequence,"protected":r.observation.protected,"loaded":r.observation.loaded,"complete":r.observation.complete,"age_ms":r.observed_at.elapsed().as_millis()}))})),
   "correlation_boundary":"Core current-owner predicates; rejected socket identity is attributed separately by liveAuthStatus"})
}
pub(super) async fn recovery_owner_trace(client:&Client,label:&str)->Value {
 let snapshot=client.handle.command(|c|Box::pin(async move{Ok(recovery_owner_predicates(c))})).await.unwrap();
 let app=client.handle.view();write_row(client.root.parent().unwrap(),"network-recovery-owner-trace.jsonl",&json!({"label":label,"side":client.root.file_name().unwrap().to_string_lossy(),"owner":snapshot,"app_state":app["connection"]["state"],"transport":app["g3"]["live_transport"],"control":app["g3"]["control"]["current"]}));snapshot
}
pub(super) async fn cold_probe_diagnostics(service:&mut Service,cold:&Client,peer:&Client,root:&std::path::Path,initial:bool){
 for (i,client) in [cold,peer].into_iter().enumerate(){let owner=recovery_owner_trace(client,"focused current pair completed").await;assert_eq!(owner["eligibility"]["production_ready"],true);assert_eq!(owner["eligibility"]["replay_matches_production"],true);let view=current_snapshot(client,None).await;assert_eq!(view["fixture_current"]["playing"],true);if initial||i==1{assert_eq!(view["g3"]["live_transport"]["attempts"],1);assert_eq!(view["g3"]["live_transport"]["failures"],0);}}
 let clock=service.command(json!({"op":"clockStatus"}));let capacity=service.command(json!({"op":"liveCapacityStatus"}));let auth=service.command(json!({"op":"liveAuthStatus"}));std::fs::write(root.join("cold-final-service-diagnostics.json"),serde_json::to_vec_pretty(&json!({"clock":clock,"capacity":capacity,"auth":auth})).unwrap()).unwrap();capacity_shape(&capacity["liveCapacity"]).unwrap();auth_shape(&auth["liveAuth"]).unwrap();assert!(capacity["liveCapacity"]["firstRetire"].is_null());assert!(capacity["liveCapacity"]["counts"].as_object().unwrap().values().all(|v|v.as_u64()==Some(0)));assert!(auth["liveAuth"]["firstFailure"].is_null());
}

#[test]fn lc1_network_owner_trace_keeps_identity_and_credential_material_as_predicates_only(){
 let(mut core,_,_)=super::super::tests::release_case();core.enable_lc1();let game=core.game.as_mut().unwrap();game.session.id="private-session-marker".into();game.session.epoch="private-epoch-marker".into();game.session.attachment="private-attachment-marker".into();game.session.access=SecretString::from("private-access-marker".to_string());
 core.lifecycle.lock().unwrap().authority.admission=Some(serde_json::from_value(json!({"generation":2,"scope":{"sessionId":"private-session-marker","sessionEpoch":"private-epoch-marker","attachmentId":"private-attachment-marker"},"owner":{"gameInstanceId":"private-owner-marker"},"sample":{"credentialId":"private-credential-marker"},"currentReport":{"revision":28,"protected":true,"contentDigest":"private-digest-marker"},"decision":{"authorized":true,"playing":false}})).unwrap());
 let trace=recovery_owner_predicates(&core);assert_eq!(trace["canonical_generation"],2);assert_eq!(trace["canonical_report"]["protected"],true);assert_eq!(trace["canonical_decision"]["playing"],false);let text=trace.to_string();for marker in ["private-session-marker","private-epoch-marker","private-attachment-marker","private-access-marker","private-owner-marker","private-credential-marker","private-digest-marker"]{assert!(!text.contains(marker),"Owner trace exposed {marker}");}
}
